/**
 * @jest-environment node
 *
 * The Relic Vault's media manifest (src/data/projects-media.json, GENERATED by scripts/encode-projects.mjs):
 * every exhibit has its clip and poster in public/projects/, AV1 webm before the H.264 fallback.
 */

import fs from 'fs'
import path from 'path'
import projectsData from '@/data/projects.json'
import media from '@/data/projects-media.json'

type Entry = {
  w: number
  h: number
  duration: number
  audio: boolean
  placeholder: boolean
  poster: string
  sources: { src: string; type: string }[]
}

const manifest = media as Record<string, Entry>
const pub = (src: string) => path.join(process.cwd(), 'public', src)

describe('projects-media.json', () => {
  it('has an entry for every project and nothing else', () => {
    expect(Object.keys(manifest)).toEqual(projectsData.map((p) => p.id))
  })

  it.each(projectsData.map((p) => p.id))('%s: its files exist under public/', (id) => {
    const entry = manifest[id]
    expect(entry.poster).toBe(`/projects/${id}.jpg`)
    expect(fs.existsSync(pub(entry.poster))).toBe(true)
    entry.sources.forEach((s) => expect(fs.existsSync(pub(s.src))).toBe(true))
  })

  it.each(projectsData.map((p) => p.id))('%s: AV1 webm first, then H.264 mp4', (id) => {
    expect(manifest[id].sources).toEqual([
      { src: `/projects/${id}.webm`, type: 'video/webm; codecs=av01.0.05M.08' },
      { src: `/projects/${id}.mp4`, type: 'video/mp4' },
    ])
  })

  it.each(projectsData.map((p) => p.id))('%s: a sane size and length', (id) => {
    const { w, h, duration, audio, placeholder } = manifest[id]
    expect(Number.isInteger(w) && Number.isInteger(h)).toBe(true)
    // the long side at 1280 at most, even dimensions for yuv420p
    expect(Math.max(w, h)).toBeLessThanOrEqual(1280)
    expect(Math.min(w, h)).toBeGreaterThanOrEqual(360)
    expect(w % 2 + (h % 2)).toBe(0)
    expect(duration).toBeGreaterThan(2)
    expect(duration).toBeLessThanOrEqual(40)
    expect(typeof audio).toBe('boolean')
    expect(typeof placeholder).toBe('boolean')
  })

  it('keeps Quadzilla portrait and the rest landscape', () => {
    projectsData.forEach((p) => {
      const { w, h } = manifest[p.id]
      expect(p.id === 'quadzilla' ? h > w : w > h).toBe(true)
    })
  })
})
